import {BillingEntitlementsService} from '../billing/billing-entitlements.service';
import {BadRequestException,ConflictException,ForbiddenException,Injectable,NotFoundException} from '@nestjs/common';
import {Prisma,type Task} from '@prisma/client';
import {checklistSchema,commentSchema,decisionSchema,dependencySchema,executionMemberSchema,milestoneSchema,phaseSchema,projectSchema,projectUpdateSchema,riskSchema,taskSchema,taskStatusSchema,taskTransitionSchema,taskUpdateSchema,transitionSchema,type ExecutionQuery,type WorkPermission,type WorkQuery} from '@work/shared-schemas';
import {NotificationService} from './notification.service';
import {validate} from '../common/validation';
import {OrganizationService} from './organization.service';
import type {WorkIdentity} from './identity.service';
import {loadAccess,relatedMember,requireGlobal,requirePermission,type WorkAccess} from './access';
const defaults=[
  ['NEW','جديدة','New','OPEN'],['OPEN','مفتوحة','Open','OPEN'],['IN_PROGRESS','قيد التنفيذ','In progress','ACTIVE'],['ON_HOLD','معلقة','On hold','HOLD'],['PENDING_REVIEW','بانتظار المراجعة','Pending review','REVIEW'],['PENDING_APPROVAL','بانتظار الاعتماد','Pending approval','APPROVAL'],['COMPLETED','مكتملة','Completed','DONE'],['CANCELLED','ملغاة','Cancelled','CANCELLED'],['REJECTED','مرفوضة','Rejected','REJECTED'],
] as const;
const defaultTransitions:Array<[string,string,WorkPermission]>=[
  ['NEW','OPEN','tasks.edit'],['NEW','CANCELLED','tasks.close'],['OPEN','IN_PROGRESS','tasks.edit'],['OPEN','ON_HOLD','tasks.edit'],['OPEN','CANCELLED','tasks.close'],
  ['IN_PROGRESS','ON_HOLD','tasks.edit'],['ON_HOLD','IN_PROGRESS','tasks.edit'],['IN_PROGRESS','PENDING_REVIEW','tasks.edit'],['IN_PROGRESS','PENDING_APPROVAL','tasks.edit'],['IN_PROGRESS','COMPLETED','tasks.edit'],
  ['PENDING_REVIEW','PENDING_APPROVAL','tasks.review'],['PENDING_REVIEW','COMPLETED','tasks.review'],['PENDING_REVIEW','REJECTED','tasks.review'],['PENDING_APPROVAL','COMPLETED','tasks.approve'],['PENDING_APPROVAL','REJECTED','tasks.approve'],
  ['REJECTED','OPEN','tasks.edit'],['COMPLETED','OPEN','tasks.close'],['CANCELLED','OPEN','tasks.close'],['ON_HOLD','CANCELLED','tasks.close'],['IN_PROGRESS','CANCELLED','tasks.close'],
];
@Injectable()
export class ExecutionService{
  constructor(private readonly organizations:OrganizationService,private readonly notifications:NotificationService,private readonly entitlements:BillingEntitlementsService){}
  async export(user:WorkIdentity,organizationId:string,kind:'tasks'|'projects',query:ExecutionQuery){await this.run(user,organizationId,async(_tx,access)=>requirePermission(access,'reports.export'));const items:Record<string,unknown>[]=[];let total:number;for(let page=1;page<=100;page++){const result=kind==='tasks'?await this.tasks(user,organizationId,{...query,page,pageSize:100}):await this.projects(user,organizationId,{...query,page,pageSize:100});total=result.total;if(total>10000)throw new BadRequestException('Narrow export filters to 10000 records');items.push(...result.items);if(items.length>=total)break;}const columns=kind==='tasks'?['number','title','status','priority','progress','startDate','dueDate','estimatedHours','costEstimate']:['number','name','status','priority','progress','startDate','endDate','budget'];const cell=(value:unknown)=>{let text=value instanceof Date?value.toISOString():String(value??'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};return {filename:kind+'.csv',csv:[columns.map(cell).join(','),...items.map(row=>columns.map(key=>cell(row[key])).join(','))].join('\r\n')};}
  private async run<T>(user:WorkIdentity,organizationId:string,operation:(tx:Prisma.TransactionClient,access:WorkAccess)=>Promise<T>){return this.organizations.execute(user,organizationId,async(tx,access)=>{await this.configure(tx,organizationId);return operation(tx,access);});}
  async configure(tx:Prisma.TransactionClient,organizationId:string){if(await tx.taskStatus.count({where:{organizationId}}))return;await tx.taskStatus.createMany({data:defaults.map(([key,nameAr,nameEn,category],position)=>({organizationId,key,nameAr,nameEn,category,position})),skipDuplicates:true});await tx.taskTransition.createMany({data:defaultTransitions.map(([fromStatus,toStatus,permission])=>({organizationId,fromStatus,toStatus,permission})),skipDuplicates:true});}
  private async number(tx:Prisma.TransactionClient,organizationId:string,kind:'TASK'|'PROJECT'){const counter=await tx.workCounter.upsert({where:{organizationId_kind:{organizationId,kind}},create:{organizationId,kind,value:1},update:{value:{increment:1}}});const settings=await tx.organizationSettings.findUnique({where:{organizationId}});return `${kind==='TASK'?settings?.taskPrefix??'T':settings?.projectPrefix??'P'}-${String(counter.value).padStart(6,'0')}`;}
  private global(access:WorkAccess,permission:WorkPermission){return access.grants.some(g=>g.permission===permission&&g.scope==='ORGANIZATION');}
  projectFinance(access:WorkAccess,permission:'budgets.read'|'budgets.manage',row:{id?:string;managerId:string;createdById:string;branchId:string|null;departmentId:string|null;teamId:string|null}){return access.grants.some(g=>g.permission===permission&&(g.scope==='ORGANIZATION'||g.scope==='OWN'&&(row.managerId===access.membershipId||row.createdById===access.membershipId)||g.scope==='PROJECT'&&g.scopeId===row.id||g.scope==='BRANCH'&&g.scopeId===row.branchId||g.scope==='DEPARTMENT'&&g.scopeId===row.departmentId||g.scope==='TEAM'&&g.scopeId===row.teamId));}
  async projectFilter(tx:Prisma.TransactionClient,access:WorkAccess,permission:WorkPermission):Promise<Prisma.ProjectWhereInput>{
    requirePermission(access,permission);const OR:Prisma.ProjectWhereInput[]=[];for(const grant of access.grants.filter(g=>g.permission===permission)){switch(grant.scope){case 'ORGANIZATION':return {};case 'OWN':OR.push({OR:[{managerId:access.membershipId},{createdById:access.membershipId},...(!permission.startsWith('budgets.')?[{members:{some:{membershipId:access.membershipId}}}]:[])]});break;case 'PROJECT':if(grant.scopeId)OR.push({id:grant.scopeId});break;case 'BRANCH':OR.push({branchId:grant.scopeId});break;case 'DEPARTMENT':OR.push({departmentId:grant.scopeId});break;case 'TEAM':OR.push({teamId:grant.scopeId});break;}}return {OR:OR.length?OR:[{id:'00000000-0000-0000-0000-000000000000'}]};
  }
  async taskFilter(tx:Prisma.TransactionClient,access:WorkAccess,permission:WorkPermission):Promise<Prisma.TaskWhereInput>{
    requirePermission(access,permission);const OR:Prisma.TaskWhereInput[]=[];const own:Prisma.TaskWhereInput={OR:[{createdById:access.membershipId},{assignedToId:access.membershipId},{reviewerId:access.membershipId},{approverId:access.membershipId},{participants:{some:{membershipId:access.membershipId}}}]};
    for(const grant of access.grants.filter(g=>g.permission===permission)){switch(grant.scope){case 'ORGANIZATION':return {};case 'OWN':OR.push(own);if(access.role==='PROJECT_MANAGER')OR.push({project:{managerId:access.membershipId}});if(permission==='tasks.read')OR.push({confidentiality:'INTERNAL',OR:[{visibility:'ORGANIZATION'},{visibility:'TEAM',project:{members:{some:{membershipId:access.membershipId}}}},{visibility:'TEAM',teamId:{in:(await tx.teamMember.findMany({where:{organizationId:access.organizationId,membershipId:access.membershipId},select:{teamId:true}})).map(row=>row.teamId)}}]});break;case 'TASK':if(grant.scopeId)OR.push({id:grant.scopeId});break;case 'PROJECT':OR.push({projectId:grant.scopeId});break;case 'DEPARTMENT':OR.push({OR:[{departmentId:grant.scopeId},{project:{departmentId:grant.scopeId}}]});break;case 'TEAM':OR.push({OR:[{teamId:grant.scopeId},{project:{teamId:grant.scopeId}}]});break;case 'BRANCH':OR.push({OR:[{department:{branchId:grant.scopeId}},{project:{branchId:grant.scopeId}}]});break;}}return {OR:OR.length?OR:[{id:'00000000-0000-0000-0000-000000000000'}]};
  }
  async project(tx:Prisma.TransactionClient,access:WorkAccess,id:string,permission:WorkPermission='projects.read'){const row=await tx.project.findFirst({where:{AND:[{organizationId:access.organizationId,id,archivedAt:null},await this.projectFilter(tx,access,permission)]}});if(!row)throw new NotFoundException('Project not found in your scope');return row;}
  async task(tx:Prisma.TransactionClient,access:WorkAccess,id:string,permission:WorkPermission='tasks.read',includeArchived=false){const row=await tx.task.findFirst({where:{AND:[{organizationId:access.organizationId,id,...(!includeArchived?{archivedAt:null}:{})},await this.taskFilter(tx,access,permission)]}});if(!row)throw new NotFoundException('Task not found in your scope');return row;}
  private async names(tx:Prisma.TransactionClient,organizationId:string,ids:Array<string|null>){const rows=await tx.membership.findMany({where:{organizationId,id:{in:ids.filter((id):id is string=>!!id)}},select:{id:true,user:{select:{displayName:true}}}});return Object.fromEntries(rows.map(row=>[row.id,row.user.displayName]));}
  private async taskLock(tx:Prisma.TransactionClient,id:string){await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${'task:'+id}))`;}
  private async change(tx:Prisma.TransactionClient,access:WorkAccess,taskId:string,action:string,detail:Prisma.InputJsonValue,requestId:string){await tx.taskChange.create({data:{organizationId:access.organizationId,taskId,actorId:access.membershipId,action,detail}});await this.organizations.audit(tx,{id:access.userId} as WorkIdentity,access.organizationId,requestId,action,'task',taskId);}
  private async structure(tx:Prisma.TransactionClient,access:WorkAccess,data:{departmentId:string|null;teamId:string|null;branchId?:string|null}){const organizationId=access.organizationId;const department=data.departmentId?await tx.department.findFirst({where:{organizationId,id:data.departmentId,archivedAt:null}}):null;if(data.departmentId&&!department)throw new NotFoundException('Department unavailable');if(data.branchId){if(!await tx.organizationBranch.findFirst({where:{organizationId,id:data.branchId,archivedAt:null}}))throw new NotFoundException('Branch unavailable');if(department&&department.branchId!==data.branchId)throw new BadRequestException('Department and branch mismatch');}if(data.teamId){const team=await tx.team.findFirst({where:{organizationId,id:data.teamId,archivedAt:null}});if(!team)throw new NotFoundException('Team unavailable');if(data.departmentId&&team.departmentId!==data.departmentId)throw new BadRequestException('Team and department mismatch');}return department;}
  private creationScope(access:WorkAccess,permission:WorkPermission,data:{departmentId:string|null;teamId:string|null;branchId?:string|null;projectId?:string|null},own:boolean){if(!access.grants.some(g=>g.permission===permission&&(g.scope==='ORGANIZATION'||g.scope==='OWN'&&own||g.scope==='DEPARTMENT'&&g.scopeId===data.departmentId||g.scope==='TEAM'&&g.scopeId===data.teamId||g.scope==='BRANCH'&&g.scopeId===data.branchId||g.scope==='PROJECT'&&g.scopeId===data.projectId)))throw new ForbiddenException('Creation outside permission scope');}
  async projects(user:WorkIdentity,organizationId:string,query:ExecutionQuery){return this.run(user,organizationId,async(tx,access)=>{const where:Prisma.ProjectWhereInput={AND:[{organizationId,archivedAt:query.view==='archived'?{not:null}:null,name:{contains:query.search,mode:'insensitive'},...(query.status?{status:query.status}:{}),...(query.priority?{priority:query.priority}:{}),...(query.departmentId?{departmentId:query.departmentId}:{}),...(query.teamId?{teamId:query.teamId}:{}),...(query.view==='overdue'?{endDate:{lt:new Date()},status:{notIn:['COMPLETED','CLOSED','CANCELLED']}}:{})},await this.projectFilter(tx,access,'projects.read')]};const items=await tx.project.findMany({where,skip:(query.page-1)*query.pageSize,take:query.pageSize,orderBy:{createdAt:'desc'},include:{_count:{select:{tasks:{where:{archivedAt:null}},members:true}}}});const completed=await tx.task.groupBy({by:['projectId'],where:{organizationId,projectId:{in:items.map(row=>row.id)},archivedAt:null,completedAt:{not:null}},_count:true});return {items:items.map(row=>({...row,budget:this.projectFinance(access,'budgets.read',row)?row.budget:null,progress:row._count.tasks?Math.round(100*(completed.find(count=>count.projectId===row.id)?._count??0)/row._count.tasks):0})),total:await tx.project.count({where})};});}
  async projectDetail(user:WorkIdentity,organizationId:string,id:string){return this.run(user,organizationId,async(tx,access)=>{const project=await this.project(tx,access,id);const tasks=await tx.task.count({where:{organizationId,projectId:id,archivedAt:null}});const completed=await tx.task.count({where:{organizationId,projectId:id,archivedAt:null,completedAt:{not:null}}});return {...project,budget:this.projectFinance(access,'budgets.read',project)?project.budget:null,actualCost:this.projectFinance(access,'budgets.read',project)?((await tx.operationalExpense.aggregate({where:{organizationId,projectId:id,status:'APPROVED'},_sum:{baseAmount:true}}))._sum.baseAmount??new Prisma.Decimal(0)).toFixed(3):null,actualHours:((await tx.timeEntry.aggregate({where:{organizationId,projectId:id},_sum:{durationSeconds:true}}))._sum.durationSeconds??0)/3600,people:await this.names(tx,organizationId,[project.managerId,project.createdById]),taskCount:tasks,completedTasks:completed,progress:tasks?Math.round(completed*100/tasks):0};});}
  private activeProject(status:string){return !['COMPLETED','CLOSED','CANCELLED'].includes(status);}
  private projectCapacityLock(tx:Prisma.TransactionClient,org:string){return tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${'PROJECT_CAP:'+org}))`;}
  private async projectCapacity(tx:Prisma.TransactionClient,org:string,id?:string){const limits=await this.entitlements.current(tx,org);if(limits.maxProjects!==null&&await tx.project.count({where:{organizationId:org,archivedAt:null,status:{notIn:['COMPLETED','CLOSED','CANCELLED']},...(id?{id:{not:id}}:{})}})>=limits.maxProjects)throw new BadRequestException({code:'BILLING_PROJECT_LIMIT',message:'Active project limit reached'});}
  async saveProject(user:WorkIdentity,organizationId:string,id:string|undefined,body:unknown,requestId:string){return this.run(user,organizationId,(tx,access)=>this.saveProjectInTransaction(tx,access,user,id,body,requestId));}
  async saveProjectInTransaction(tx:Prisma.TransactionClient,access:WorkAccess,user:WorkIdentity,id:string|undefined,body:unknown,requestId:string){const organizationId=access.organizationId;await this.projectCapacityLock(tx,organizationId);await this.configure(tx,organizationId);const parsed=id?validate(projectUpdateSchema,body):validate(projectSchema,body);const {version,...data}={...parsed,version:'version' in parsed?parsed.version:undefined};await relatedMember(tx,organizationId,data.managerId);const department=await this.structure(tx,access,data);if(id){await tx.$queryRaw`SELECT id FROM projects WHERE organization_id=${organizationId}::uuid AND id=${id}::uuid FOR UPDATE`;const existing=await this.project(tx,access,id,'projects.edit');if(existing.version!==version)throw new ConflictException('Project changed');if(this.activeProject(data.status)&&!this.activeProject(existing.status))await this.projectCapacity(tx,organizationId,id);if(!body||typeof body!=='object'||!('budget' in body))data.budget=existing.budget.toString();if(!new Prisma.Decimal(data.budget).equals(existing.budget)&&!this.projectFinance(access,'budgets.manage',existing))throw new ForbiddenException('Budget management permission required');if(!new Prisma.Decimal(data.budget).equals(existing.budget)){await this.entitlements.require(tx,organizationId,'BUDGETS');await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${'finance:'+organizationId}))`;const spent=(await tx.operationalExpense.aggregate({where:{organizationId,projectId:id,status:'APPROVED'},_sum:{baseAmount:true}}))._sum.baseAmount??new Prisma.Decimal(0);if(new Prisma.Decimal(data.budget).lessThan(spent))throw new BadRequestException('Project budget cannot be reduced below approved expenses');}if(!this.global(access,'projects.manage')&&(data.managerId!==existing.managerId||data.departmentId!==existing.departmentId||data.teamId!==existing.teamId||data.branchId!==existing.branchId))throw new ForbiddenException('Only organization project managers may reassign project scope');if(['COMPLETED','CLOSED'].includes(data.status)){if(await tx.task.count({where:{organizationId,projectId:id,archivedAt:null,completedAt:null,status:{notIn:(await tx.taskStatus.findMany({where:{organizationId,category:'CANCELLED'},select:{key:true}})).map(row=>row.key)}}}))throw new BadRequestException('Project has unfinished tasks');requirePermission(access,'projects.manage');}const updated=await tx.project.updateMany({where:{organizationId,id,version},data:{...data,version:{increment:1}}});if(!updated.count)throw new ConflictException('Project changed');await this.organizations.audit(tx,user,organizationId,requestId,'PROJECT_UPDATED','project',id);const saved=await tx.project.findUniqueOrThrow({where:{organizationId_id:{organizationId,id}}});return {...saved,budget:this.projectFinance(access,'budgets.read',saved)?saved.budget:null};}
    if(this.activeProject(data.status))await this.projectCapacity(tx,organizationId);this.creationScope(access,'projects.create',{...data,branchId:data.branchId??department?.branchId},data.managerId===access.membershipId);if(['COMPLETED','CLOSED'].includes(data.status))throw new BadRequestException('Create a planned or active project');if(new Prisma.Decimal(data.budget).greaterThan(0))await this.entitlements.require(tx,organizationId,'BUDGETS');if(new Prisma.Decimal(data.budget).greaterThan(0)&&!this.projectFinance(access,'budgets.manage',{...data,createdById:access.membershipId}))throw new ForbiddenException('Budget management permission required');const project=await tx.project.create({data:{...data,organizationId,createdById:access.membershipId,number:await this.number(tx,organizationId,'PROJECT')}});await tx.projectMember.create({data:{organizationId,projectId:project.id,membershipId:data.managerId}});await this.organizations.audit(tx,user,organizationId,requestId,'PROJECT_CREATED','project',project.id);return {...project,budget:this.projectFinance(access,'budgets.read',project)?project.budget:null};}
  async archiveProject(user:WorkIdentity,organizationId:string,id:string,restore:boolean,requestId:string){return this.run(user,organizationId,async(tx,access)=>{await this.projectCapacityLock(tx,organizationId);await tx.$queryRaw`SELECT id FROM projects WHERE organization_id=${organizationId}::uuid AND id=${id}::uuid FOR UPDATE`;if(!await tx.project.findFirst({where:{AND:[{organizationId,id},await this.projectFilter(tx,access,'projects.delete')]}}))throw new NotFoundException('Project not found in your scope');if(restore){const row=await tx.project.findUniqueOrThrow({where:{organizationId_id:{organizationId,id}}});if(row.archivedAt&&this.activeProject(row.status))await this.projectCapacity(tx,organizationId,id);}const cancelled=(await tx.taskStatus.findMany({where:{organizationId,category:'CANCELLED'},select:{key:true}})).map(row=>row.key);if(!restore&&await tx.task.count({where:{organizationId,projectId:id,archivedAt:null,completedAt:null,status:{notIn:cancelled}}}))throw new BadRequestException('Active tasks must be resolved before project archival');await tx.project.update({where:{organizationId_id:{organizationId,id}},data:{archivedAt:restore?null:new Date(),version:{increment:1}}});await this.organizations.audit(tx,user,organizationId,requestId,restore?'PROJECT_RESTORED':'PROJECT_ARCHIVED','project',id);return {ok:true};});}
  async projectRecords(user:WorkIdentity,organizationId:string,id:string,resource:string,query:WorkQuery){return this.run(user,organizationId,async(tx,access)=>{await this.project(tx,access,id);const options={where:{organizationId,projectId:id},skip:(query.page-1)*query.pageSize,take:query.pageSize};switch(resource){case 'members':{const rows=await tx.projectMember.findMany({...options,orderBy:{membershipId:'asc'}});const people=await this.names(tx,organizationId,rows.map(row=>row.membershipId));return {items:rows.map(row=>({...row,id:row.membershipId,displayName:people[row.membershipId]})),total:await tx.projectMember.count({where:options.where})};}case 'phases':return {items:await tx.projectPhase.findMany({...options,orderBy:{position:'asc'}}),total:await tx.projectPhase.count({where:options.where})};case 'milestones':return {items:await tx.projectMilestone.findMany({...options,orderBy:{dueDate:'asc'}}),total:await tx.projectMilestone.count({where:options.where})};case 'risks':return {items:await tx.projectRisk.findMany(options),total:await tx.projectRisk.count({where:options.where})};case 'decisions':return {items:await tx.projectDecision.findMany({...options,orderBy:{createdAt:'desc'}}),total:await tx.projectDecision.count({where:options.where})};default:throw new NotFoundException('Unknown project resource');}});}
  async saveProjectRecord(user:WorkIdentity,organizationId:string,projectId:string,resource:string,id:string|undefined,body:unknown,requestId:string){return this.run(user,organizationId,async(tx,access)=>{await this.project(tx,access,projectId,'projects.manage');let result:{id?:string;membershipId?:string};const where={organizationId,projectId,id};switch(resource){case 'members':{const data=validate(executionMemberSchema,body);await relatedMember(tx,organizationId,data.membershipId);result=await tx.projectMember.upsert({where:{organizationId_projectId_membershipId:{organizationId,projectId,membershipId:data.membershipId}},create:{organizationId,projectId,...data},update:{}});break;}case 'phases':{const data=validate(phaseSchema,body);result=id?await tx.projectPhase.update({where,data}):await tx.projectPhase.create({data:{organizationId,projectId,...data}});break;}case 'milestones':{const {completed,...data}=validate(milestoneSchema,body);result=id?await tx.projectMilestone.update({where,data:{...data,completedAt:completed?new Date():null}}):await tx.projectMilestone.create({data:{organizationId,projectId,...data,completedAt:completed?new Date():null}});break;}case 'risks':{const data=validate(riskSchema,body);await relatedMember(tx,organizationId,data.ownerId);result=id?await tx.projectRisk.update({where,data}):await tx.projectRisk.create({data:{organizationId,projectId,...data}});break;}case 'decisions':{if(id)throw new BadRequestException('Decisions are immutable');result=await tx.projectDecision.create({data:{organizationId,projectId,createdById:access.membershipId,...validate(decisionSchema,body)}});break;}default:throw new NotFoundException('Unknown project resource');}await this.organizations.audit(tx,user,organizationId,requestId,'PROJECT_'+resource.toUpperCase()+'_SAVED','project',projectId);return result;});}
  async removeProjectMember(user:WorkIdentity,organizationId:string,projectId:string,membershipId:string,requestId:string){return this.run(user,organizationId,async(tx,access)=>{const project=await this.project(tx,access,projectId,'projects.manage');if(project.managerId===membershipId)throw new BadRequestException('Project manager must remain a member');await tx.projectMember.deleteMany({where:{organizationId,projectId,membershipId}});await this.organizations.audit(tx,user,organizationId,requestId,'PROJECT_MEMBER_REMOVED','project',projectId);return {ok:true};});}
  async tasks(user:WorkIdentity,organizationId:string,query:ExecutionQuery){return this.run(user,organizationId,async(tx,access)=>{const where:Prisma.TaskWhereInput={AND:[{organizationId,archivedAt:query.view==='archived'?{not:null}:null,OR:[{title:{contains:query.search,mode:'insensitive'}},{number:{contains:query.search,mode:'insensitive'}}],...(query.status?{status:query.status}:{}),...(query.priority?{priority:query.priority}:{}),...(query.projectId?{projectId:query.projectId}:{}),...(query.assignedToId?{assignedToId:query.assignedToId}:{}),...(query.departmentId?{departmentId:query.departmentId}:{}),...(query.teamId?{teamId:query.teamId}:{}),...(query.view==='mine'?{assignedToId:access.membershipId}:{}),...(query.view==='team'?{teamId:{in:(await tx.teamMember.findMany({where:{organizationId,membershipId:access.membershipId},select:{teamId:true}})).map(row=>row.teamId)}}:{}),...(query.view==='approval'?{AND:[{OR:[{reviewerId:access.membershipId,status:'PENDING_REVIEW'},{approverId:access.membershipId,status:'PENDING_APPROVAL'}]}]}:{}),...(query.view==='overdue'?{dueDate:{lt:new Date()},completedAt:null,status:{not:'CANCELLED'}}:query.from||query.to?{dueDate:{...(query.from?{gte:new Date(query.from)}:{}),...(query.to?{lte:new Date(query.to)}:{})}}:{})},await this.taskFilter(tx,access,'tasks.read')]};return {items:await tx.task.findMany({where,skip:(query.page-1)*query.pageSize,take:query.pageSize,orderBy:[{dueDate:'asc'},{createdAt:'desc'}],include:{project:{select:{name:true,number:true}},_count:{select:{comments:true,checklist:true}}}}),total:await tx.task.count({where}),page:query.page,pageSize:query.pageSize};});}
  async taskDetail(user:WorkIdentity,organizationId:string,id:string){return this.run(user,organizationId,async(tx,access)=>{const task=await this.task(tx,access,id,'tasks.read',true);return {...task,actualHours:((await tx.timeEntry.aggregate({where:{organizationId,taskId:id},_sum:{durationSeconds:true}}))._sum.durationSeconds??0)/3600,people:await this.names(tx,organizationId,[task.createdById,task.assignedToId,task.reviewerId,task.approverId]),transitions:await tx.taskTransition.findMany({where:{organizationId,fromStatus:task.status}})};});}
  private async taskRelations(tx:Prisma.TransactionClient,access:WorkAccess,data:Prisma.TaskUncheckedCreateInput){for(const value of [data.assignedToId,data.reviewerId,data.approverId])await relatedMember(tx,access.organizationId,value);if(data.assignedToId&&(data.reviewerId===data.assignedToId||data.approverId===data.assignedToId))throw new BadRequestException('Assignee cannot review or approve own work');await this.structure(tx,access,{departmentId:data.departmentId??null,teamId:data.teamId??null});if(data.projectId){await tx.$queryRaw`SELECT id FROM projects WHERE organization_id=${access.organizationId}::uuid AND id=${data.projectId}::uuid FOR SHARE`;const project=await this.project(tx,access,data.projectId);if(['COMPLETED','CANCELLED','CLOSED'].includes(project.status))throw new BadRequestException('Project is closed');if(data.departmentId&&project.departmentId&&data.departmentId!==project.departmentId)throw new BadRequestException('Project and task department mismatch');}if(data.phaseId&&!await tx.projectPhase.findFirst({where:{organizationId:access.organizationId,id:data.phaseId,projectId:data.projectId??'00000000-0000-0000-0000-000000000000'}}))throw new NotFoundException('Project phase unavailable');if(data.parentTaskId){const parent=await this.task(tx,access,data.parentTaskId);if(parent.projectId!==(data.projectId??null))throw new BadRequestException('Parent task belongs to another project');}}
  async saveTask(user:WorkIdentity,organizationId:string,id:string|undefined,body:unknown,requestId:string){return this.run(user,organizationId,async(tx,access)=>{if(id)await this.taskLock(tx,id);const parsed=id?validate(taskUpdateSchema,body):validate(taskSchema,body);const {version,...input}={...parsed,version:'version' in parsed?parsed.version:undefined};const data={...input,organizationId,createdById:access.membershipId,number:''};await this.taskRelations(tx,access,data);const projectScope=input.projectId?await this.project(tx,access,input.projectId):null;const departmentScope=input.departmentId?await tx.department.findUnique({where:{organizationId_id:{organizationId,id:input.departmentId}}}):null;const targetScope={...input,departmentId:input.departmentId??projectScope?.departmentId??null,teamId:input.teamId??projectScope?.teamId??null,branchId:departmentScope?.branchId??projectScope?.branchId??null};if(id){const existing=await this.task(tx,access,id,'tasks.edit');if(existing.version!==version)throw new ConflictException('Task changed');const currentCategory=(await tx.taskStatus.findUniqueOrThrow({where:{organizationId_key:{organizationId,key:existing.status}}})).category;if(existing.completedAt||currentCategory==='CANCELLED'||existing.approvedAt)throw new BadRequestException('Reopen task before changing approved work');if(input.parentTaskId!==existing.parentTaskId)throw new BadRequestException('Parent cannot be changed after creation');const assignmentChanged=['assignedToId','reviewerId','approverId','projectId','departmentId','teamId','visibility','confidentiality'].some(key=>Reflect.get(input,key)!==Reflect.get(existing,key));if(assignmentChanged){await this.task(tx,access,id,'tasks.assign');if(input.projectId!==existing.projectId||input.departmentId!==existing.departmentId||input.teamId!==existing.teamId)this.creationScope(access,'tasks.assign',targetScope,input.assignedToId===access.membershipId);}const updated=await tx.task.updateMany({where:{organizationId,id,version},data:{...input,reviewedAt:null,approvedAt:null,...(['REVIEW','APPROVAL'].includes(currentCategory)?{status:'OPEN'}:{}),version:{increment:1}}});if(!updated.count)throw new ConflictException('Task changed');await this.change(tx,access,id,'TASK_UPDATED',{fields:Object.keys(input).filter(key=>String(Reflect.get(input,key))!==String(Reflect.get(existing,key)))},requestId);return tx.task.findUniqueOrThrow({where:{organizationId_id:{organizationId,id}}});}
    this.creationScope(access,'tasks.create',targetScope,input.assignedToId===null||input.assignedToId===access.membershipId||access.role==='PROJECT_MANAGER'&&projectScope?.managerId===access.membershipId);if(input.assignedToId&&input.assignedToId!==access.membershipId||input.reviewerId||input.approverId||input.visibility!=='PRIVATE')this.creationScope(access,'tasks.assign',targetScope,access.role==='PROJECT_MANAGER'&&projectScope?.managerId===access.membershipId);const task=await tx.task.create({data:{...input,organizationId,createdById:access.membershipId,number:await this.number(tx,organizationId,'TASK')}});await this.change(tx,access,task.id,'TASK_CREATED',{number:task.number},requestId);await this.notifications.emit(tx,organizationId,[task.assignedToId],'TASK_ASSIGNED','tasks',task.id,`assigned:${task.id}:1`);return task;});}
  async transition(user:WorkIdentity,organizationId:string,id:string,body:unknown,requestId:string){const data=validate(transitionSchema,body);return this.run(user,organizationId,(tx,access)=>this.transitionInTransaction(tx,access,id,data,requestId));}
  async transitionInTransaction(tx:Prisma.TransactionClient,access:WorkAccess,id:string,data:ReturnType<typeof transitionSchema.parse>,requestId:string,automated=false){const organizationId=access.organizationId;await this.taskLock(tx,id);const task=await this.task(tx,access,id);if(task.version!==data.version)throw new ConflictException('Task changed');const transition=await tx.taskTransition.findUnique({where:{organizationId_fromStatus_toStatus:{organizationId,fromStatus:task.status,toStatus:data.status}}});const status=await tx.taskStatus.findUnique({where:{organizationId_key:{organizationId,key:data.status}}});if(!transition||!status?.active)throw new BadRequestException('Transition not allowed');const source=await tx.taskStatus.findUniqueOrThrow({where:{organizationId_key:{organizationId,key:task.status}}});if(automated&&(task.approvedAt||!['OPEN','ACTIVE','HOLD'].includes(source.category)))throw new ForbiddenException({code:'APPROVAL_REQUIRES_HUMAN',message:'Protected tasks require a user action'});const review=source.category==='REVIEW'&&['APPROVAL','DONE','REJECTED'].includes(status.category),approve=source.category==='APPROVAL'&&['DONE','REJECTED'].includes(status.category);if((review||approve)&&task.assignedToId===access.membershipId)throw new ForbiddenException('An independent reviewer or approver is required');if(review){if(task.reviewerId!==access.membershipId)throw new ForbiddenException('Assigned reviewer required');await this.task(tx,access,id,'tasks.review');}else if(approve){if(task.approverId!==access.membershipId)throw new ForbiddenException('Assigned approver required');await this.task(tx,access,id,'tasks.approve');}else await this.task(tx,access,id,transition.permission as WorkPermission);
    if((source.category==='DONE'||source.category==='CANCELLED')&&!data.reason)throw new BadRequestException('Reopening requires a reason');
    if(['ACTIVE','REVIEW','APPROVAL','DONE'].includes(status.category)){const blocked=await tx.taskDependency.count({where:{organizationId,taskId:id,predecessor:{completedAt:null}}});if(blocked){if(!data.overrideDependencies)throw new BadRequestException('Incomplete predecessors block this transition');await this.task(tx,access,id,'tasks.override_dependencies');if(data.reason.length<5)throw new BadRequestException('Dependency override requires a documented reason');await this.change(tx,access,id,'DEPENDENCY_OVERRIDE',{blockedPredecessors:blocked,reason:data.reason},requestId);}}
    const reviewedAt=review&&status.category!=='REJECTED'?new Date():task.reviewedAt,approvedAt=approve&&status.category!=='REJECTED'?new Date():task.approvedAt;
    if(status.category==='REVIEW'&&!task.reviewerId)throw new BadRequestException('No reviewer assigned');if(status.category==='APPROVAL'&&(!task.approverId||task.reviewerId&&!reviewedAt))throw new BadRequestException('Review requirement is not satisfied');
    if(status.category==='DONE'){if(task.reviewerId&&!reviewedAt||task.approverId&&!approvedAt)throw new BadRequestException('Approval requirements are not satisfied');if(await tx.taskChecklistItem.count({where:{organizationId,taskId:id,completed:false}}))throw new BadRequestException('Checklist is incomplete');if(await tx.task.count({where:{organizationId,parentTaskId:id,archivedAt:null,completedAt:null,status:{not:'CANCELLED'}}}))throw new BadRequestException('Subtasks are incomplete');}
    const reopen=['DONE','CANCELLED','REJECTED'].includes(source.category)||status.category==='REJECTED';const result=await tx.task.updateMany({where:{organizationId,id,version:data.version},data:{status:data.status,version:{increment:1},reviewedAt:reopen?null:reviewedAt,approvedAt:reopen?null:approvedAt,completedAt:status.category==='DONE'?new Date():null,progress:status.category==='DONE'?100:Math.min(task.progress,99)}});if(!result.count)throw new ConflictException('Task changed');await this.change(tx,access,id,'TASK_STATUS_CHANGED',{from:task.status,to:data.status,reason:data.reason},requestId);await this.notifications.emit(tx,organizationId,status.category==='REVIEW'?[task.reviewerId]:status.category==='APPROVAL'?[task.approverId]:[task.assignedToId,task.createdById],status.category==='REVIEW'?'REVIEW_REQUIRED':status.category==='APPROVAL'?'APPROVAL_REQUIRED':status.category==='DONE'?'TASK_COMPLETED':'TASK_UPDATED','tasks',id,`status:${id}:${data.version+1}`);if(status.category==='DONE'&&task.recurrence!=='NONE')await this.recur(tx,access,task,requestId);return tx.task.findUniqueOrThrow({where:{organizationId_id:{organizationId,id}}});}

  private async recur(tx:Prisma.TransactionClient,access:WorkAccess,task:Task,requestId:string){
    const organizationId=access.organizationId;await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${'recurrence:'+task.id}))`;
    if(await tx.taskChange.findFirst({where:{organizationId,action:'TASK_RECURRENCE_CREATED',detail:{path:['sourceTaskId'],equals:task.id}}}))return;
    const creator=await tx.membership.findUnique({where:{organizationId_id:{organizationId,id:task.createdById}},include:{user:{select:{id:true,emailVerifiedAt:true,disabledAt:true,deletedAt:true}}}});
    const skip=()=>this.change(tx,access,task.id,'TASK_RECURRENCE_SKIPPED',{code:'RECURRENCE_SOURCE_UNAVAILABLE'},requestId);
    if(!creator?.active||!creator.user.emailVerifiedAt||creator.user.disabledAt||creator.user.deletedAt){await skip();return;}
    const timezone=(await tx.organization.findUniqueOrThrow({where:{id:organizationId},select:{timezone:true}})).timezone,lineage=await tx.taskChange.findFirst({where:{organizationId,taskId:task.id,action:'TASK_RECURRENCE_CREATED'},select:{detail:true}}),metadata=lineage?.detail&&typeof lineage.detail==='object'&&!Array.isArray(lineage.detail)?lineage.detail:{};
    const anchor=(key:string,fallback:Date|null)=>{const value=metadata[key];return typeof value==='string'&&Number.isFinite(Date.parse(value))?new Date(value):fallback;},baseDue=task.dueDate??new Date(),dueAnchor=anchor('dueAnchor',baseDue)!,startAnchor=anchor('startAnchor',task.startDate);
    const next=async(value:Date|null,original:Date|null)=>{if(!value)return null;return (await tx.$queryRaw<Array<{next_at:Date}>>`SELECT work_next_recurrence(${value}::timestamptz,${task.recurrence},${timezone},${original}::timestamptz) AS next_at`)[0]!.next_at;};
    const dueDate=await next(baseDue,dueAnchor);if(task.recurrenceUntil&&dueDate!>task.recurrenceUntil)return;
    const input=Object.fromEntries(Object.keys(taskSchema.shape).map(key=>[key,Reflect.get(task,key)]));input.progress=0;input.dueDate=dueDate;input.startDate=await next(task.startDate,startAnchor);
    let created:Task;
    try{await tx.$executeRaw`SELECT set_config('app.user_id',${creator.user.id},true)`;const origin=await loadAccess(tx,creator.user.id,organizationId);await this.task(tx,origin,task.id);created=await this.taskFromDecision(tx,origin,JSON.parse(JSON.stringify(input)),requestId,'recurrence');}
    catch(error){if(error instanceof ForbiddenException||error instanceof NotFoundException||error instanceof BadRequestException){await tx.$executeRaw`SELECT set_config('app.user_id',${access.userId},true)`;await skip();return;}throw error;}
    await tx.$executeRaw`SELECT set_config('app.user_id',${access.userId},true)`;
    await tx.taskChecklistItem.createMany({data:(await tx.taskChecklistItem.findMany({where:{organizationId,taskId:task.id}})).map(item=>({organizationId,taskId:created.id,title:item.title,position:item.position}))});
    await this.change(tx,access,created.id,'TASK_RECURRENCE_CREATED',{sourceTaskId:task.id,dueAnchor:dueAnchor.toISOString(),startAnchor:startAnchor?.toISOString()??null},requestId);
  }
  async archiveTask(user:WorkIdentity,organizationId:string,id:string,restore:boolean,requestId:string){return this.run(user,organizationId,async(tx,access)=>{await this.taskLock(tx,id);const archivedTask=await this.task(tx,access,id,'tasks.delete',true);if(restore&&archivedTask.projectId){await tx.$queryRaw`SELECT id FROM projects WHERE organization_id=${organizationId}::uuid AND id=${archivedTask.projectId}::uuid FOR SHARE`;const project=await this.project(tx,access,archivedTask.projectId);if(['COMPLETED','CLOSED','CANCELLED'].includes(project.status))throw new BadRequestException('Project is closed');}if(!restore&&await tx.taskDependency.count({where:{organizationId,predecessorId:id,task:{archivedAt:null,completedAt:null}}}))throw new BadRequestException('Task has active dependents');await tx.task.update({where:{organizationId_id:{organizationId,id}},data:{archivedAt:restore?null:new Date(),version:{increment:1}}});await this.change(tx,access,id,restore?'TASK_RESTORED':'TASK_ARCHIVED',{},requestId);return {ok:true};});}
  async taskRecords(user:WorkIdentity,organizationId:string,id:string,resource:string,query:WorkQuery){return this.run(user,organizationId,async(tx,access)=>{await this.task(tx,access,id,'tasks.read',true);const options={where:{organizationId,taskId:id},skip:(query.page-1)*query.pageSize,take:query.pageSize};switch(resource){case 'participants':{const rows=await tx.taskParticipant.findMany(options);const people=await this.names(tx,organizationId,rows.map(row=>row.membershipId));return {items:rows.map(row=>({...row,id:row.membershipId,displayName:people[row.membershipId]})),total:await tx.taskParticipant.count({where:options.where})};}case 'checklist':return {items:await tx.taskChecklistItem.findMany({...options,orderBy:{position:'asc'}}),total:await tx.taskChecklistItem.count({where:options.where})};case 'comments':{const rows=await tx.taskComment.findMany({...options,orderBy:{createdAt:'desc'}});const people=await this.names(tx,organizationId,rows.map(row=>row.authorId));return {items:rows.map(row=>({...row,authorName:people[row.authorId]})),total:await tx.taskComment.count({where:options.where})};}case 'dependencies':{const rows=await tx.taskDependency.findMany({...options,include:{predecessor:{select:{id:true,title:true,number:true,completedAt:true}}}});const items=[];for(const row of rows){try{await this.task(tx,access,row.predecessorId);items.push({...row,id:row.predecessorId});}catch(error){if(!(error instanceof NotFoundException||error instanceof ForbiddenException))throw error;items.push({id:row.predecessorId,restricted:true});}}return {items,total:await tx.taskDependency.count({where:options.where})};}case 'changes':return {items:await tx.taskChange.findMany({...options,orderBy:{createdAt:'desc'}}),total:await tx.taskChange.count({where:options.where})};default:throw new NotFoundException('Unknown task resource');}});}
  async saveTaskRecord(user:WorkIdentity,organizationId:string,taskId:string,resource:string,id:string|undefined,body:unknown,requestId:string){return this.run(user,organizationId,async(tx,access)=>{await this.taskLock(tx,taskId);const task=await this.task(tx,access,taskId,resource==='comments'?'tasks.comment':resource==='participants'?'tasks.assign':'tasks.edit');if(resource!=='comments'&&(task.completedAt||task.approvedAt))throw new BadRequestException('Reopen task before editing');let result:{id?:string;membershipId?:string;predecessorId?:string};switch(resource){case 'comments':if(id)throw new BadRequestException('Comments are immutable');result=await tx.taskComment.create({data:{organizationId,taskId,authorId:access.membershipId,...validate(commentSchema,body)}});break;case 'checklist':{const data=validate(checklistSchema,body);result=id?await tx.taskChecklistItem.update({where:{id,organizationId,taskId},data}):await tx.taskChecklistItem.create({data:{organizationId,taskId,...data}});break;}case 'participants':{const data=validate(executionMemberSchema,body);await relatedMember(tx,organizationId,data.membershipId);result=await tx.taskParticipant.upsert({where:{organizationId_taskId_membershipId:{organizationId,taskId,membershipId:data.membershipId}},create:{organizationId,taskId,...data},update:{}});break;}case 'dependencies':{const data=validate(dependencySchema,body);await this.task(tx,access,data.predecessorId);await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${'dependencies:'+organizationId}))`;const cycle=await tx.$queryRaw<Array<{id:string}>>`WITH RECURSIVE predecessors(id) AS (SELECT ${data.predecessorId}::uuid UNION SELECT d.predecessor_id FROM task_dependencies d JOIN predecessors p ON p.id=d.task_id WHERE d.organization_id=${organizationId}::uuid) SELECT id FROM predecessors WHERE id=${taskId}::uuid`;if(cycle.length)throw new BadRequestException('Circular dependency');result=await tx.taskDependency.create({data:{organizationId,taskId,...data}});break;}default:throw new NotFoundException('Unknown task resource');}if(resource!=='comments')await tx.task.update({where:{organizationId_id:{organizationId,id:taskId}},data:{version:{increment:1},reviewedAt:null,approvedAt:null,...(['PENDING_REVIEW','PENDING_APPROVAL'].includes(task.status)?{status:'OPEN'}:{})}});await this.change(tx,access,taskId,'TASK_'+resource.toUpperCase()+'_SAVED',{recordId:result.id??result.membershipId??result.predecessorId??''},requestId);return result;});}
  async removeTaskRecord(user:WorkIdentity,organizationId:string,taskId:string,resource:string,id:string,requestId:string){return this.run(user,organizationId,async(tx,access)=>{await this.taskLock(tx,taskId);const task=await this.task(tx,access,taskId,resource==='participants'?'tasks.assign':'tasks.edit');if(task.completedAt||task.approvedAt)throw new BadRequestException('Reopen task before editing');if(resource==='participants')await tx.taskParticipant.deleteMany({where:{organizationId,taskId,membershipId:id}});else if(resource==='dependencies')await tx.taskDependency.deleteMany({where:{organizationId,taskId,predecessorId:id}});else if(resource==='checklist')await tx.taskChecklistItem.deleteMany({where:{organizationId,taskId,id}});else throw new BadRequestException('Record cannot be deleted');await tx.task.update({where:{organizationId_id:{organizationId,id:taskId}},data:{version:{increment:1},reviewedAt:null,approvedAt:null}});await this.change(tx,access,taskId,'TASK_'+resource.toUpperCase()+'_REMOVED',{recordId:id},requestId);return {ok:true};});}

  async automateTask(tx:Prisma.TransactionClient,access:WorkAccess,id:string,action:{type:'TASK_ASSIGN';membershipId:string}|{type:'TASK_PROGRESS';progress:number},expectedVersion:number,requestId:string){const organizationId=access.organizationId;await this.configure(tx,organizationId);await this.taskLock(tx,id);const task=await this.task(tx,access,id,action.type==='TASK_ASSIGN'?'tasks.assign':'tasks.edit');if(task.version!==expectedVersion)throw new ConflictException('Task changed');const source=await tx.taskStatus.findUniqueOrThrow({where:{organizationId_key:{organizationId,key:task.status}}});if(task.approvedAt||task.completedAt||!['OPEN','ACTIVE','HOLD'].includes(source.category))throw new ForbiddenException({code:'APPROVAL_REQUIRES_HUMAN',message:'Protected tasks require a user action'});let data:Prisma.TaskUpdateManyMutationInput;let detail:Prisma.InputJsonValue;if(action.type==='TASK_ASSIGN'){await relatedMember(tx,organizationId,action.membershipId);if(task.reviewerId===action.membershipId||task.approverId===action.membershipId)throw new BadRequestException('Assignee cannot review or approve own work');data={assignedToId:action.membershipId};detail={assignedToId:{before:task.assignedToId,after:action.membershipId}};}else{if(!Number.isInteger(action.progress)||action.progress<0||action.progress>99)throw new BadRequestException('Completion must use a task transition');data={progress:action.progress};detail={progress:{before:task.progress,after:action.progress}};}const changed=await tx.task.updateMany({where:{organizationId,id,version:task.version},data:{...data,reviewedAt:null,approvedAt:null,version:{increment:1}}});if(!changed.count)throw new ConflictException('Task changed');await this.change(tx,access,id,'WORKFLOW_'+action.type,detail,requestId);if(action.type==='TASK_ASSIGN')await this.notifications.emit(tx,organizationId,[action.membershipId],'TASK_ASSIGNED','tasks',id,`assigned:${id}:${task.version+1}`);return tx.task.findUniqueOrThrow({where:{organizationId_id:{organizationId,id}}});}
  async taskFromDecision(tx:Prisma.TransactionClient,access:WorkAccess,body:unknown,requestId:string,source='meeting_decision'){await this.configure(tx,access.organizationId);const data=validate(taskSchema,body);const organizationId=access.organizationId;await this.taskRelations(tx,access,{...data,organizationId,number:'',createdById:access.membershipId});const project=data.projectId?await this.project(tx,access,data.projectId):null;const scope={...data,departmentId:data.departmentId??project?.departmentId??null,teamId:data.teamId??project?.teamId??null,branchId:project?.branchId??null};this.creationScope(access,'tasks.create',scope,data.assignedToId===access.membershipId||data.assignedToId===null||access.role==='PROJECT_MANAGER'&&project?.managerId===access.membershipId);if(data.assignedToId&&data.assignedToId!==access.membershipId)this.creationScope(access,'tasks.assign',scope,access.role==='PROJECT_MANAGER'&&project?.managerId===access.membershipId);const task=await tx.task.create({data:{...data,organizationId,createdById:access.membershipId,number:await this.number(tx,organizationId,'TASK')}});await this.change(tx,access,task.id,'TASK_CREATED',{number:task.number,source},requestId);await this.notifications.emit(tx,organizationId,[task.assignedToId],'TASK_ASSIGNED','tasks',task.id,`assigned:${task.id}:1`);return task;}
  async configuration(user:WorkIdentity,organizationId:string){return this.run(user,organizationId,async(tx)=>({statuses:await tx.taskStatus.findMany({where:{organizationId},orderBy:{position:'asc'}}),transitions:await tx.taskTransition.findMany({where:{organizationId}})}));}
  async saveConfiguration(user:WorkIdentity,organizationId:string,resource:string,body:unknown,requestId:string){return this.run(user,organizationId,async(tx,access)=>{requireGlobal(access,'organization.manage');let result;if(resource==='statuses'){const data=validate(taskStatusSchema,body);const current=await tx.taskStatus.findUnique({where:{organizationId_key:{organizationId,key:data.key}}});if(current&&current.category!==data.category&&await tx.task.count({where:{organizationId,status:data.key}}))throw new BadRequestException('Cannot change category of a used status');if(data.key==='NEW'&&(!data.active||data.category!=='OPEN'))throw new BadRequestException('Default initial status must remain active');result=await tx.taskStatus.upsert({where:{organizationId_key:{organizationId,key:data.key}},create:{organizationId,...data},update:data});}else if(resource==='transitions'){const data=validate(taskTransitionSchema,body);result=await tx.taskTransition.upsert({where:{organizationId_fromStatus_toStatus:{organizationId,fromStatus:data.fromStatus,toStatus:data.toStatus}},create:{organizationId,...data},update:{permission:data.permission}});}else throw new NotFoundException('Unknown configuration resource');await this.organizations.audit(tx,user,organizationId,requestId,'TASK_CONFIGURATION_UPDATED','organization',organizationId);return result;});}
  async removeTransition(user:WorkIdentity,organizationId:string,fromStatus:string,toStatus:string,requestId:string){return this.run(user,organizationId,async(tx,access)=>{requireGlobal(access,'organization.manage');await tx.taskTransition.deleteMany({where:{organizationId,fromStatus,toStatus}});await this.organizations.audit(tx,user,organizationId,requestId,'TASK_TRANSITION_REMOVED','organization',organizationId);return {ok:true};});}
  async metrics(user:WorkIdentity,organizationId:string){return this.run(user,organizationId,async(tx,access)=>{const tasks:Prisma.TaskWhereInput={AND:[{organizationId,archivedAt:null},await this.taskFilter(tx,access,'tasks.read')]};const projects:Prisma.ProjectWhereInput={AND:[{organizationId,archivedAt:null},await this.projectFilter(tx,access,'projects.read')]};return {tasks:await tx.task.count({where:tasks}),completed:await tx.task.count({where:{AND:[tasks,{completedAt:{not:null}}]}}),overdue:await tx.task.count({where:{AND:[tasks,{dueDate:{lt:new Date()},completedAt:null,status:{not:'CANCELLED'}}]}}),projects:await tx.project.count({where:projects}),byStatus:await tx.task.groupBy({by:['status'],where:tasks,_count:true})};});}
}
